package com.wheeloffate;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import javax.swing.JComponent;
import javax.swing.Timer;

public class ConfettiOverlay extends JComponent
{
	private static final int CONFETTI_COUNT = 80;
	private static final double DURATION_MS = 3500.0;
	private static final int INTERVAL_MS = 16;

	private static final Color[] COLORS = {
		new Color(255, 215, 0),    // Gold
		new Color(231, 76, 60),    // Red
		new Color(46, 204, 113),   // Green
		new Color(52, 152, 219),   // Blue
		new Color(241, 196, 15),   // Yellow
		new Color(155, 89, 182),   // Purple
		new Color(230, 126, 34),   // Orange
		new Color(255, 255, 255),  // White
		new Color(236, 112, 160),  // Pink
		new Color(26, 188, 156),   // Teal
	};

	private final List<Particle> particles = new ArrayList<>();
	private Timer timer;
	private long startTime;

	public ConfettiOverlay()
	{
		setOpaque(false);
	}

	public void fire()
	{
		stop();
		particles.clear();

		int width = getWidth();
		int height = getHeight();
		if (width <= 0 || height <= 0)
		{
			return;
		}

		Random rand = new Random();

		for (int i = 0; i < CONFETTI_COUNT; i++)
		{
			// Spawn from random positions along the top
			double x = rand.nextDouble() * width;
			double y = -5 - rand.nextDouble() * 20;

			double vx = -2.0 + rand.nextDouble() * 4.0;
			double vy = 1.0 + rand.nextDouble() * 3.0;

			Color color = COLORS[rand.nextInt(COLORS.length)];
			int size = 4 + rand.nextInt(6);
			int shape = rand.nextInt(3);
			double rotation = rand.nextDouble() * 360;
			double rotSpeed = -10 + rand.nextDouble() * 20;
			// Stagger start so they don't all appear at once
			double delay = rand.nextDouble() * 800;

			particles.add(new Particle(x, y, vx, vy, color, size, shape, rotation, rotSpeed, delay));
		}

		// Also burst some from center
		int cx = width / 2;
		int cy = height / 3;
		for (int i = 0; i < CONFETTI_COUNT / 2; i++)
		{
			double angle = rand.nextDouble() * Math.PI * 2;
			double speed = 2.0 + rand.nextDouble() * 4.0;
			double vx = Math.cos(angle) * speed;
			double vy = Math.sin(angle) * speed - 2.0;

			Color color = COLORS[rand.nextInt(COLORS.length)];
			int size = 3 + rand.nextInt(6);
			int shape = rand.nextInt(3);
			double rotation = rand.nextDouble() * 360;
			double rotSpeed = -10 + rand.nextDouble() * 20;

			particles.add(new Particle(cx, cy, vx, vy, color, size, shape, rotation, rotSpeed, 0));
		}

		startTime = System.currentTimeMillis();
		timer = new Timer(INTERVAL_MS, e -> update());
		timer.start();
	}

	public void stop()
	{
		if (timer != null)
		{
			timer.stop();
			timer = null;
		}
		particles.clear();
		repaint();
	}

	private void update()
	{
		long elapsed = System.currentTimeMillis() - startTime;
		if (elapsed > DURATION_MS)
		{
			stop();
			return;
		}

		for (Particle p : particles)
		{
			if (elapsed < p.delay)
			{
				continue;
			}
			p.x += p.vx;
			p.y += p.vy;
			p.vy += 0.06; // gravity
			p.vx *= 0.995; // air drag
			p.rotation += p.rotSpeed;

			double life = (elapsed - p.delay) / (DURATION_MS - p.delay);
			// Fade out in the last 40%
			if (life > 0.6)
			{
				p.alpha = Math.max(0, 1.0 - (life - 0.6) / 0.4);
			}
			else
			{
				p.alpha = 1.0;
			}
		}

		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		if (particles.isEmpty())
		{
			return;
		}

		Graphics2D g2d = (Graphics2D) g.create();
		g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		long elapsed = System.currentTimeMillis() - startTime;

		for (Particle p : particles)
		{
			if (elapsed < p.delay || p.alpha <= 0)
			{
				continue;
			}

			int alpha = (int) (p.alpha * 255);
			Color c = new Color(p.color.getRed(), p.color.getGreen(), p.color.getBlue(), alpha);
			g2d.setColor(c);

			Graphics2D g2 = (Graphics2D) g2d.create();
			g2.translate(p.x, p.y);
			g2.rotate(Math.toRadians(p.rotation));

			switch (p.shape)
			{
				case 0: // Square
					g2.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
					break;
				case 1: // Circle
					g2.fillOval(-p.size / 2, -p.size / 2, p.size, p.size);
					break;
				case 2: // Ribbon
					g2.fillRect(-p.size, -p.size / 4, p.size * 2, p.size / 2);
					break;
			}

			g2.dispose();
		}

		g2d.dispose();
	}

	private static class Particle
	{
		double x, y, vx, vy;
		Color color;
		int size;
		int shape;
		double rotation;
		double rotSpeed;
		double delay;
		double alpha;

		Particle(double x, double y, double vx, double vy, Color color,
			int size, int shape, double rotation, double rotSpeed, double delay)
		{
			this.x = x;
			this.y = y;
			this.vx = vx;
			this.vy = vy;
			this.color = color;
			this.size = size;
			this.shape = shape;
			this.rotation = rotation;
			this.rotSpeed = rotSpeed;
			this.delay = delay;
			this.alpha = 1.0;
		}
	}
}

package com.wheeloffate;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.WebSocket;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class MqttRelay
{
	private static final String BROKER_URI = "ws://broker.hivemq.com:8000/mqtt";
	private static final String TOPIC_PREFIX = "wheeloffate/";
	private static final int KEEP_ALIVE_SECONDS = 30;

	private final Consumer<String> onMessage;
	private final Runnable onConnected;
	private final Runnable onDisconnected;

	private WebSocket webSocket;
	private String topic;
	private String clientId;
	private volatile boolean connected;
	private ScheduledExecutorService pingScheduler;
	private ScheduledFuture<?> pingTask;
	private ByteBuffer accumulatedData = ByteBuffer.allocate(0);

	public MqttRelay(Consumer<String> onMessage, Runnable onConnected, Runnable onDisconnected)
	{
		this.onMessage = onMessage;
		this.onConnected = onConnected;
		this.onDisconnected = onDisconnected;
		this.clientId = "wof-" + UUID.randomUUID().toString().substring(0, 8);
	}

	public CompletableFuture<Void> connect(String roomCode)
	{
		this.topic = TOPIC_PREFIX + roomCode;

		return HttpClient.newHttpClient()
			.newWebSocketBuilder()
			.subprotocols("mqtt")
			.buildAsync(URI.create(BROKER_URI), new WebSocket.Listener()
			{
				@Override
				public void onOpen(WebSocket ws)
				{
					log.info("WebSocket connected to broker");
					webSocket = ws;
					sendMqttConnect();
					ws.request(1);
				}

				@Override
				public CompletionStage<?> onBinary(WebSocket ws, ByteBuffer data, boolean last)
				{
					// Accumulate data if message is fragmented
					ByteBuffer combined;
					if (accumulatedData.remaining() > 0)
					{
						combined = ByteBuffer.allocate(accumulatedData.remaining() + data.remaining());
						combined.put(accumulatedData);
						combined.put(data);
						combined.flip();
					}
					else
					{
						combined = data;
					}

					if (!last)
					{
						accumulatedData = ByteBuffer.allocate(combined.remaining());
						accumulatedData.put(combined);
						accumulatedData.flip();
						ws.request(1);
						return null;
					}

					accumulatedData = ByteBuffer.allocate(0);
					handleMqttPacket(combined);
					ws.request(1);
					return null;
				}

				@Override
				public CompletionStage<?> onClose(WebSocket ws, int statusCode, String reason)
				{
					log.info("WebSocket closed: {} {}", statusCode, reason);
					connected = false;
					stopPing();
					if (onDisconnected != null)
					{
						onDisconnected.run();
					}
					return null;
				}

				@Override
				public void onError(WebSocket ws, Throwable error)
				{
					log.error("WebSocket error", error);
					connected = false;
					stopPing();
					if (onDisconnected != null)
					{
						onDisconnected.run();
					}
				}
			})
			.thenAccept(ws -> webSocket = ws);
	}

	public void publish(String message)
	{
		if (!connected || webSocket == null)
		{
			return;
		}
		sendMqttPublish(topic, message);
	}

	public void disconnect()
	{
		connected = false;
		stopPing();
		if (webSocket != null)
		{
			try
			{
				// MQTT DISCONNECT packet
				webSocket.sendBinary(ByteBuffer.wrap(new byte[]{(byte) 0xE0, 0x00}), true);
				webSocket.sendClose(WebSocket.NORMAL_CLOSURE, "bye");
			}
			catch (Exception ignored)
			{
			}
			webSocket = null;
		}
	}

	public boolean isConnected()
	{
		return connected;
	}

	// === MQTT Packet Construction ===

	private void sendMqttConnect()
	{
		byte[] clientIdBytes = clientId.getBytes(StandardCharsets.UTF_8);

		// Variable header: protocol name "MQTT", level 4, flags, keep alive
		byte[] variableHeader = {
			0x00, 0x04, 'M', 'Q', 'T', 'T', // Protocol name
			0x04,                              // Protocol level (MQTT 3.1.1)
			0x02,                              // Connect flags (clean session)
			(byte) (KEEP_ALIVE_SECONDS >> 8),  // Keep alive MSB
			(byte) (KEEP_ALIVE_SECONDS & 0xFF) // Keep alive LSB
		};

		// Payload: client ID
		byte[] payload = new byte[2 + clientIdBytes.length];
		payload[0] = (byte) (clientIdBytes.length >> 8);
		payload[1] = (byte) (clientIdBytes.length & 0xFF);
		System.arraycopy(clientIdBytes, 0, payload, 2, clientIdBytes.length);

		int remainingLength = variableHeader.length + payload.length;
		byte[] packet = buildPacket(0x10, variableHeader, payload, remainingLength);
		webSocket.sendBinary(ByteBuffer.wrap(packet), true);
	}

	private void sendMqttSubscribe(String topicFilter)
	{
		byte[] topicBytes = topicFilter.getBytes(StandardCharsets.UTF_8);

		// Variable header: packet identifier
		byte[] variableHeader = {0x00, 0x01};

		// Payload: topic filter + QoS 0
		byte[] payload = new byte[2 + topicBytes.length + 1];
		payload[0] = (byte) (topicBytes.length >> 8);
		payload[1] = (byte) (topicBytes.length & 0xFF);
		System.arraycopy(topicBytes, 0, payload, 2, topicBytes.length);
		payload[payload.length - 1] = 0x00; // QoS 0

		int remainingLength = variableHeader.length + payload.length;
		byte[] packet = buildPacket(0x82, variableHeader, payload, remainingLength);
		webSocket.sendBinary(ByteBuffer.wrap(packet), true);
	}

	private void sendMqttPublish(String topicName, String message)
	{
		byte[] topicBytes = topicName.getBytes(StandardCharsets.UTF_8);
		byte[] messageBytes = message.getBytes(StandardCharsets.UTF_8);

		// Variable header: topic name
		byte[] variableHeader = new byte[2 + topicBytes.length];
		variableHeader[0] = (byte) (topicBytes.length >> 8);
		variableHeader[1] = (byte) (topicBytes.length & 0xFF);
		System.arraycopy(topicBytes, 0, variableHeader, 2, topicBytes.length);

		int remainingLength = variableHeader.length + messageBytes.length;
		byte[] packet = buildPacket(0x30, variableHeader, messageBytes, remainingLength);
		webSocket.sendBinary(ByteBuffer.wrap(packet), true);
	}

	private void sendPing()
	{
		if (webSocket != null && connected)
		{
			webSocket.sendBinary(ByteBuffer.wrap(new byte[]{(byte) 0xC0, 0x00}), true);
		}
	}

	private byte[] buildPacket(int type, byte[] variableHeader, byte[] payload, int remainingLength)
	{
		byte[] lengthBytes = encodeRemainingLength(remainingLength);
		byte[] packet = new byte[1 + lengthBytes.length + variableHeader.length + payload.length];
		packet[0] = (byte) type;
		System.arraycopy(lengthBytes, 0, packet, 1, lengthBytes.length);
		System.arraycopy(variableHeader, 0, packet, 1 + lengthBytes.length, variableHeader.length);
		System.arraycopy(payload, 0, packet, 1 + lengthBytes.length + variableHeader.length, payload.length);
		return packet;
	}

	private byte[] encodeRemainingLength(int length)
	{
		byte[] encoded = new byte[4];
		int idx = 0;
		do
		{
			byte b = (byte) (length % 128);
			length /= 128;
			if (length > 0)
			{
				b |= 0x80;
			}
			encoded[idx++] = b;
		}
		while (length > 0);

		byte[] result = new byte[idx];
		System.arraycopy(encoded, 0, result, 0, idx);
		return result;
	}

	// === MQTT Packet Parsing ===

	private void handleMqttPacket(ByteBuffer buffer)
	{
		while (buffer.hasRemaining())
		{
			int startPos = buffer.position();
			if (buffer.remaining() < 2)
			{
				break;
			}

			int firstByte = buffer.get() & 0xFF;
			int packetType = firstByte >> 4;

			// Decode remaining length
			int remainingLength = 0;
			int multiplier = 1;
			byte encoded;
			int lengthBytes = 0;
			do
			{
				if (!buffer.hasRemaining())
				{
					buffer.position(startPos);
					return;
				}
				encoded = buffer.get();
				lengthBytes++;
				remainingLength += (encoded & 0x7F) * multiplier;
				multiplier *= 128;
			}
			while ((encoded & 0x80) != 0 && lengthBytes < 4);

			if (buffer.remaining() < remainingLength)
			{
				buffer.position(startPos);
				return;
			}

			switch (packetType)
			{
				case 2: // CONNACK
					handleConnAck(buffer, remainingLength);
					break;
				case 3: // PUBLISH
					handlePublish(buffer, remainingLength, firstByte);
					break;
				case 9: // SUBACK
					buffer.position(buffer.position() + remainingLength);
					log.info("Subscribed to topic: {}", topic);
					break;
				case 13: // PINGRESP
					break;
				default:
					buffer.position(buffer.position() + remainingLength);
					break;
			}
		}
	}

	private void handleConnAck(ByteBuffer buffer, int remainingLength)
	{
		if (remainingLength >= 2)
		{
			buffer.get(); // session present
			int returnCode = buffer.get() & 0xFF;

			if (returnCode == 0)
			{
				connected = true;
				log.info("MQTT connected, subscribing to {}", topic);
				sendMqttSubscribe(topic);
				startPing();
				if (onConnected != null)
				{
					onConnected.run();
				}
			}
			else
			{
				log.error("MQTT connect failed with code {}", returnCode);
			}
		}
		else
		{
			buffer.position(buffer.position() + remainingLength);
		}
	}

	private void handlePublish(ByteBuffer buffer, int remainingLength, int firstByte)
	{
		int startPos = buffer.position();

		// Topic length
		int topicLen = ((buffer.get() & 0xFF) << 8) | (buffer.get() & 0xFF);
		byte[] topicBytes = new byte[topicLen];
		buffer.get(topicBytes);

		int consumed = 2 + topicLen;

		// QoS > 0 has packet identifier (we use QoS 0 so skip)
		int qos = (firstByte >> 1) & 0x03;
		if (qos > 0)
		{
			buffer.getShort(); // packet identifier
			consumed += 2;
		}

		// Payload
		int payloadLen = remainingLength - consumed;
		if (payloadLen > 0)
		{
			byte[] payloadBytes = new byte[payloadLen];
			buffer.get(payloadBytes);
			String payload = new String(payloadBytes, StandardCharsets.UTF_8);

			if (onMessage != null)
			{
				onMessage.accept(payload);
			}
		}
		else
		{
			buffer.position(startPos + remainingLength);
		}
	}

	private void startPing()
	{
		pingScheduler = new ScheduledThreadPoolExecutor(1, r ->
		{
			Thread t = new Thread(r, "WheelSync-Ping");
			t.setDaemon(true);
			return t;
		});
		pingTask = pingScheduler.scheduleAtFixedRate(
			this::sendPing, KEEP_ALIVE_SECONDS, KEEP_ALIVE_SECONDS, TimeUnit.SECONDS);
	}

	private void stopPing()
	{
		if (pingTask != null)
		{
			pingTask.cancel(false);
			pingTask = null;
		}
		if (pingScheduler != null)
		{
			pingScheduler.shutdownNow();
			pingScheduler = null;
		}
	}
}

package com.wheeloffate;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.List;

import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.Timer;

public class WheelComponent extends JComponent
{
	private static final int WHEEL_SIZE = 190;
	private static final int PADDING = 10;
	private static final int PREFERRED_SIZE = WHEEL_SIZE + PADDING * 2;
	private static final int ANIMATION_INTERVAL_MS = 16; // ~60fps
	private static final double SPIN_DURATION_MS = 4000.0;
	private static final double MIN_TOTAL_ROTATIONS = 5.0;
	private static final int POINTER_SIZE = 14;
	private static final Color[] SLICE_COLORS = {
		new Color(231, 76, 60),    // Red
		new Color(46, 204, 113),   // Green
		new Color(52, 152, 219),   // Blue
		new Color(241, 196, 15),   // Yellow
		new Color(155, 89, 182),   // Purple
		new Color(230, 126, 34),   // Orange
		new Color(26, 188, 156),   // Teal
		new Color(236, 112, 160),  // Pink
		new Color(52, 73, 94),     // Dark blue
		new Color(127, 140, 141),  // Gray
		new Color(192, 57, 43),    // Dark red
		new Color(39, 174, 96),    // Dark green
	};

	private static final Color BACKGROUND_COLOR = new Color(30, 30, 30);
	private static final Color BORDER_COLOR = new Color(200, 200, 200);
	private static final Color POINTER_COLOR = new Color(255, 255, 255);
	private static final Color TEXT_COLOR = Color.WHITE;
	private static final Color TEXT_SHADOW_COLOR = new Color(0, 0, 0, 160);
	private static final Color WINNER_GLOW_COLOR = new Color(255, 215, 0, 100);

	private List<WheelEntry> entries = new ArrayList<>();
	private double currentAngle = 0;
	private boolean spinning = false;
	private Timer animationTimer;
	private long spinStartTime;
	private double startAngle;
	private double targetAngle;
	private int winnerIndex = -1;
	private boolean showWinner = false;
	private int winnerFlashCount = 0;
	private Timer winnerFlashTimer;
	private Consumer<WheelEntry> onSpinComplete;

	public WheelComponent()
	{
		setPreferredSize(new Dimension(PREFERRED_SIZE, PREFERRED_SIZE));
		setMinimumSize(new Dimension(PREFERRED_SIZE, PREFERRED_SIZE));
		setBackground(BACKGROUND_COLOR);
		setOpaque(true);
	}

	public void setEntries(List<WheelEntry> entries)
	{
		this.entries = new ArrayList<>(entries);
		winnerIndex = -1;
		showWinner = false;
		repaint();
	}

	public void setOnSpinComplete(Consumer<WheelEntry> callback)
	{
		this.onSpinComplete = callback;
	}

	public boolean isSpinning()
	{
		return spinning;
	}

	public void spin(int winnerIdx)
	{
		if (spinning || entries.isEmpty())
		{
			return;
		}

		stopWinnerFlash();
		winnerIndex = -1;
		showWinner = false;
		spinning = true;

		// Always start from 0 so all clients see the same wheel
		currentAngle = 0;
		startAngle = 0;

		double sliceAngle = 360.0 / entries.size();

		double winnerMiddle = winnerIdx * sliceAngle + sliceAngle / 2.0;
		double desiredAngle = 90.0 - winnerMiddle;
		desiredAngle = ((desiredAngle % 360.0) + 360.0) % 360.0;

		double extraRotations = MIN_TOTAL_ROTATIONS + 3.0;
		targetAngle = desiredAngle + extraRotations * 360.0;

		spinStartTime = System.currentTimeMillis();

		animationTimer = new Timer(ANIMATION_INTERVAL_MS, e -> updateAnimation());
		animationTimer.start();
	}

	private void updateAnimation()
	{
		long elapsed = System.currentTimeMillis() - spinStartTime;
		double progress = Math.min(elapsed / SPIN_DURATION_MS, 1.0);

		double easedProgress = 1.0 - Math.pow(1.0 - progress, 3.0);

		currentAngle = startAngle + (targetAngle - startAngle) * easedProgress;

		if (progress >= 1.0)
		{
			spinning = false;
			animationTimer.stop();
			animationTimer = null;
			currentAngle = ((targetAngle % 360.0) + 360.0) % 360.0;

			winnerIndex = getSliceAtPointer();
			startWinnerFlash();

			if (onSpinComplete != null && winnerIndex >= 0 && winnerIndex < entries.size())
			{
				onSpinComplete.accept(entries.get(winnerIndex));
			}
		}

		repaint();
	}

	private int getSliceAtPointer()
	{
		if (entries.isEmpty())
		{
			return -1;
		}

		double sliceAngle = 360.0 / entries.size();
		double normalizedAngle = ((90.0 - currentAngle) % 360.0 + 360.0) % 360.0;
		return (int) (normalizedAngle / sliceAngle) % entries.size();
	}

	// === Winner Flash ===

	private void startWinnerFlash()
	{
		showWinner = true;
		winnerFlashCount = 0;
		winnerFlashTimer = new Timer(300, e ->
		{
			winnerFlashCount++;
			showWinner = !showWinner;
			if (winnerFlashCount >= 8)
			{
				showWinner = true;
				((Timer) e.getSource()).stop();
				winnerFlashTimer = null;
			}
			repaint();
		});
		winnerFlashTimer.start();
	}

	private void stopWinnerFlash()
	{
		if (winnerFlashTimer != null)
		{
			winnerFlashTimer.stop();
			winnerFlashTimer = null;
		}
	}

	// === Painting ===

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Graphics2D g2d = (Graphics2D) g.create();
		g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2d.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		int width = getWidth();
		int height = getHeight();

		// Background
		g2d.setColor(BACKGROUND_COLOR);
		g2d.fillRect(0, 0, width, height);

		if (entries.isEmpty())
		{
			g2d.setColor(Color.GRAY);
			g2d.setFont(new Font("SansSerif", Font.PLAIN, 12));
			String msg = "Add entries to spin!";
			FontMetrics fm = g2d.getFontMetrics();
			g2d.drawString(msg, (width - fm.stringWidth(msg)) / 2, height / 2);
			g2d.dispose();
			return;
		}

		int wheelDiameter = Math.min(width, height) - PADDING * 2;
		int wheelX = (width - wheelDiameter) / 2;
		int wheelY = (height - wheelDiameter) / 2;
		int centerX = width / 2;
		int centerY = height / 2;
		double radius = wheelDiameter / 2.0;

		double sliceAngle = 360.0 / entries.size();

		// Draw slices
		for (int i = 0; i < entries.size(); i++)
		{
			double startDeg = currentAngle + i * sliceAngle;
			Color baseColor = SLICE_COLORS[i % SLICE_COLORS.length];

			if (winnerIndex == i && showWinner && !spinning)
			{
				baseColor = baseColor.brighter().brighter();
			}

			g2d.setColor(baseColor);
			g2d.fill(new Arc2D.Double(wheelX, wheelY, wheelDiameter, wheelDiameter,
				startDeg, sliceAngle, Arc2D.PIE));

			g2d.setColor(new Color(20, 20, 20));
			g2d.setStroke(new BasicStroke(1.5f));
			g2d.draw(new Arc2D.Double(wheelX, wheelY, wheelDiameter, wheelDiameter,
				startDeg, sliceAngle, Arc2D.PIE));
		}

		// Draw text on slices
		g2d.setFont(new Font("SansSerif", Font.BOLD, Math.max(9, Math.min(12, (int) (radius / 10)))));
		FontMetrics fm = g2d.getFontMetrics();

		for (int i = 0; i < entries.size(); i++)
		{
			double midAngle = Math.toRadians(currentAngle + i * sliceAngle + sliceAngle / 2.0);
			double textRadius = radius * 0.62;
			int textX = (int) (centerX + textRadius * Math.cos(midAngle));
			int textY = (int) (centerY - textRadius * Math.sin(midAngle));

			String name = entries.get(i).getName();
			if (fm.stringWidth(name) > radius * 0.85)
			{
				while (name.length() > 3 && fm.stringWidth(name + "..") > radius * 0.85)
				{
					name = name.substring(0, name.length() - 1);
				}
				name = name + "..";
			}

			g2d.setColor(TEXT_SHADOW_COLOR);
			g2d.drawString(name, textX - fm.stringWidth(name) / 2 + 1, textY + fm.getAscent() / 2 + 1);
			g2d.setColor(TEXT_COLOR);
			g2d.drawString(name, textX - fm.stringWidth(name) / 2, textY + fm.getAscent() / 2);
		}

		// Outer ring
		g2d.setColor(BORDER_COLOR);
		g2d.setStroke(new BasicStroke(3f));
		g2d.drawOval(wheelX, wheelY, wheelDiameter, wheelDiameter);

		// Center circle
		int centerDotSize = 16;
		g2d.setColor(new Color(50, 50, 50));
		g2d.fillOval(centerX - centerDotSize / 2, centerY - centerDotSize / 2, centerDotSize, centerDotSize);
		g2d.setColor(BORDER_COLOR);
		g2d.setStroke(new BasicStroke(2f));
		g2d.drawOval(centerX - centerDotSize / 2, centerY - centerDotSize / 2, centerDotSize, centerDotSize);

		// Winner glow
		if (winnerIndex >= 0 && showWinner && !spinning)
		{
			g2d.setColor(WINNER_GLOW_COLOR);
			g2d.setStroke(new BasicStroke(5f));
			g2d.drawOval(wheelX - 3, wheelY - 3, wheelDiameter + 6, wheelDiameter + 6);
		}

		// Pointer
		drawPointer(g2d, centerX, wheelY - 2);

		g2d.dispose();
	}

	private void drawPointer(Graphics2D g2d, int x, int y)
	{
		Path2D pointer = new Path2D.Double();
		pointer.moveTo(x, y + POINTER_SIZE + 2);
		pointer.lineTo(x - POINTER_SIZE / 2.0, y - 2);
		pointer.lineTo(x + POINTER_SIZE / 2.0, y - 2);
		pointer.closePath();

		g2d.setColor(POINTER_COLOR);
		g2d.fill(pointer);
		g2d.setColor(new Color(40, 40, 40));
		g2d.setStroke(new BasicStroke(1.5f));
		g2d.draw(pointer);
	}

	public void reset()
	{
		if (animationTimer != null)
		{
			animationTimer.stop();
			animationTimer = null;
		}
		stopWinnerFlash();
		spinning = false;
		currentAngle = 0;
		winnerIndex = -1;
		showWinner = false;
		repaint();
	}

}

